package com.mantou.salesdialer.contacts;
import java.time.*;import java.util.*;import com.mantou.salesdialer.contacts.PhoneIntakeModel.DataClass;
public final class PilotPermitCheck {
 static int checks;static void check(boolean v){checks++;if(!v)throw new AssertionError("PERMIT_ASSERTION_"+checks);}static void fail(Runnable r,String code){checks++;try{r.run();}catch(RuntimeException e){if(code.equals(e.getMessage()))return;throw new AssertionError(e);}throw new AssertionError("EXPECTED_"+code);}
 public static void main(String[] args){long now=Instant.parse("2026-10-19T01:00:00Z").toEpochMilli();var ticket=WorkspaceTimerModel.create(1,now,now,1000,"boot","a".repeat(32));var permit=new PilotPermit(DataClass.LOCAL_PHONE_INTAKE,"b".repeat(32),"LOCAL-TARGET-"+"c".repeat(32),1,"d".repeat(64),"e".repeat(32),ticket);check(permit.fingerprint().matches("[a-f0-9]{64}"));check(permit.fingerprint().equals(new PilotPermit(DataClass.LOCAL_PHONE_INTAKE,permit.slot,permit.targetId,1,permit.accountKey,permit.installationKey,ticket).fingerprint()));check(!permit.fingerprint().equals(new PilotPermit(DataClass.LOCAL_PHONE_INTAKE,permit.slot,permit.targetId,2,permit.accountKey,permit.installationKey,ticket).fingerprint()));check(!permit.fingerprint().equals(new PilotPermit(DataClass.LOCAL_PHONE_INTAKE,permit.slot,permit.targetId,1,"f".repeat(64),permit.installationKey,ticket).fingerprint()));fail(()->new PilotPermit(DataClass.FORMAT_FIXTURE,permit.slot,permit.targetId,1,permit.accountKey,permit.installationKey,ticket),"FORMAT_FIXTURE_ONLY");fail(()->new PilotPermit(DataClass.LOCAL_PHONE_INTAKE,"bad",permit.targetId,1,permit.accountKey,permit.installationKey,ticket),"INVALID_PILOT_PERMIT");System.out.println("T693 explicit real-source local permit binds slot/target/revision/SIM/installation/ticket fingerprint passed");
 permit.due(now,1000,"boot");checks++;permit.due(now+30000,31000,"boot");checks++;fail(()->permit.due(now-1,999,"boot"),"EARLY_TIMER");fail(()->permit.due(now+30001,31001,"boot"),"EXPIRED");fail(()->permit.due(now,1000,"different"),"TIMER_CLOCK_CHANGED");fail(()->permit.due(now+3000,1000,"boot"),"TIMER_CLOCK_CHANGED");System.out.println("T694 dual-clock/boot and inclusive 30 second window reuse existing timer gate passed");System.out.println("PASS: "+checks+" assertions; 2 pilot-permit scenarios; no telephone");}
}
